const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const query = item.query || {};
const companyId = Number(query.company_id || 0);
const connectionKey = String(query.connection_key || '').trim();
let registry = {};
try { registry = JSON.parse($env.XVOND_TELEGRAM_ROUTES_JSON || '{}'); }
catch (_e) { return [{json:{success:false,_dispatch:'reject',code:'registry_invalid'}}]; }
const routeKey = `${companyId}:${connectionKey}`;
const route = registry[routeKey];
if (!companyId || !connectionKey || !route) return [{json:{success:false,_dispatch:'reject',code:'route_not_found'}}];
const supplied = String(headers['x-telegram-bot-api-secret-token'] || headers['X-Telegram-Bot-Api-Secret-Token'] || '');
const expected = String(route.webhook_secret || '');
if (!expected || supplied !== expected) return [{json:{success:false,_dispatch:'reject',code:'unauthorized'}}];
const message = body.message || body.edited_message || null;
const text = String(message?.text || message?.caption || '').trim();
const chatId = String(message?.chat?.id || '');
const updateId = String(body.update_id ?? '');
if (!message || !text || !chatId || !updateId) return [{json:{success:true,_dispatch:'ignore',ignored:true}}];
return [{json:{
  success:true,
  _dispatch:'xvond',
  payload:{
    company_id:Number(route.company_id || companyId),
    agent_id:Number(route.agent_id || 0),
    channel_id:Number(route.channel_id || 0),
    channel_type:'telegram',
    external_contact_id:chatId,
    external_message_id:updateId,
    message:text
  }
}}];

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const supplied = String(headers['x-xvond-channel-secret'] || headers['X-Xvond-Channel-Secret'] || '');
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '').trim();
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};
const companyId = Number(body.company_id || 0);
const connectionKey = String(data.connection_key || '').trim();
let registry = {};
try { registry = JSON.parse($env.XVOND_TELEGRAM_ROUTES_JSON || '{}'); }
catch (_e) { return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Telegram route registry is invalid',error_code:'provider_not_configured',data:null}}]; }
const routeKey = `${companyId}:${connectionKey}`;
const route = registry[routeKey];
if (!route || !route.bot_token || !route.provider_secret) return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Telegram route is not configured',error_code:'provider_not_configured',data:null}}];
if (!supplied || supplied !== String(route.provider_secret)) return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Unauthorized Telegram provider request',error_code:'unauthorized',data:null}}];
if (action !== 'channel.send') return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Unsupported Telegram provider action',error_code:'unsupported_action',data:null}}];
const chatId = String(data.external_contact_id || '').trim();
const message = String(data.message || '').trim();
if (!requestId || !chatId || !message) return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Invalid Telegram send contract',error_code:'invalid_contract',data:null}}];
return [{json:{
  success:true,
  _dispatch:'telegram_send',
  request_id:requestId,
  action,
  bot_token:String(route.bot_token),
  chat_id:chatId,
  message,
  idempotency_key:String(data.idempotency_key || '').trim()
}}];

const response = $input.first().json;
const request = $('Validate Telegram Send').first().json;
if (!response || response.ok !== true || !response.result || response.result.message_id === undefined) {
  return [{json:{success:false,request_id:request.request_id,action:request.action,error:'Telegram provider rejected the send',error_code:'provider_rejected',data:null}}];
}
return [{json:{
  success:true,
  request_id:request.request_id,
  action:request.action,
  data:{provider_message_id:String(response.result.message_id)},
  error:null
}}];
